\begin{question}
    下列关于根式大小比较的选项中，正确的是： \paren[C]
    \begin{choices}
        \item $2\sqrt{3} > 3\sqrt{2}$ 
        \item $\sqrt[3]{5} < \sqrt{2}$ 
        \item $3\sqrt{5} < 4\sqrt{3}$ 
        \item $\sqrt[3]{3} > \sqrt{3}$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：}
    \begin{itemize}
        \item A: $2\sqrt{3} = \sqrt{12} < \sqrt{18} = 3\sqrt{2} \quad (\times)$
        \item B: $\sqrt[3]{5} = \sqrt[6]{25} > \sqrt[6]{8} = \sqrt{2} \quad (\times)$
        \item C: $3\sqrt{5} = \sqrt{45} < \sqrt{48} = 4\sqrt{3} \quad (\checkmark)$
        \item D: $\sqrt[3]{3} = \sqrt[6]{9} < \sqrt[6]{27} = \sqrt{3} \quad (\times)$
    \end{itemize}
    故选 C。
\end{solution}

\begin{question}
    若 $x > 0$，将 $\sqrt[3]{x^2} \cdot \sqrt[6]{x}$ 化简为最简根式的结果是： \paren[B]
    \begin{choices}
        \item $\sqrt{x}$ \item $\sqrt[6]{x^5}$ \item $\sqrt[3]{x}$ \item $x$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    $\sqrt[3]{x^2} \cdot \sqrt[6]{x} = x^{\frac{2}{3}} \cdot x^{\frac{1}{6}} = x^{\frac{4}{6} + \frac{1}{6}} = x^{\frac{5}{6}} = \sqrt[6]{x^5}$ \\
    故选 B。
\end{solution}

\begin{question}
    已知线段 $AB$ 的端点坐标分别为 $A(1, 2)$ 和 $B(4, 8)$，点 $P$ 在线段 $AB$ 上，且 $AP:PB = 1:2$，则点 $P$ 的坐标是： \paren[A]
    \begin{choices}
        \item $(2, 4)$ \item $(3, 6)$ \item $(2.5, 5)$ \item $(5, 10)$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    根据线段的定比分点公式，若点 $A(x_1, y_1)$，$B(x_2, y_2)$，且点 $P$ 分有向线段 $AB$ 的比为 $\lambda = \frac{AP}{PB}$，则 $P$ 点坐标为： \\
    $x = \frac{x_1 + \lambda x_2}{1 + \lambda}$， $y = \frac{y_1 + \lambda y_2}{1 + \lambda}$。 \\
    本题中 $\lambda = \frac{1}{2}$，代入已知坐标： \\
    $x = \frac{1 + \frac{1}{2} \times 4}{1 + \frac{1}{2}} = \frac{3}{\frac{3}{2}} = 2$ \\
    $y = \frac{2 + \frac{1}{2} \times 8}{1 + \frac{1}{2}} = \frac{6}{\frac{3}{2}} = 4$ \\
    所以点 $P$ 的坐标为 $(2, 4)$。 \\
    故选 A。
\end{solution}

\begin{question}
    已知点 $A(1, 2)$ 和 $B(4, 5)$，点 $P$ 在线段 $AB$ 的延长线上，且 $|AP|:|PB| = 2:1$，则点 $P$ 的坐标是： \paren[C]
    \begin{choices}
        \item $(3, 4)$ \item $(-2, -1)$ \item $(7, 8)$ \item $(2, 3)$
    \end{choices}
\end{question}
\begin{solution}
    \textbf{解析：} \\
    因为点 $P$ 在线段 $AB$ 的延长线上，所以点 $P$ 为线段 $AB$ 的外分点。 \\
    由 $|AP|:|PB| = 2:1$ 且 $P$ 在 $B$ 点外侧可知，点 $P$ 分有向线段 $AB$ 的定比为负值，即 $\lambda = -2$。 \\
    根据定比分点坐标公式 $x = \frac{x_1 + \lambda x_2}{1 + \lambda}$， $y = \frac{y_1 + \lambda y_2}{1 + \lambda}$，代入已知数据可得： \\
    $x = \frac{1 + (-2) \times 4}{1 + (-2)} = \frac{1 - 8}{-1} = 7$ \\
    $y = \frac{2 + (-2) \times 5}{1 + (-2)} = \frac{2 - 10}{-1} = 8$ \\
    所以点 $P$ 的坐标为 $(7, 8)$。 \\
    \textbf{干扰项分析：} \\
    若误当作内分点（代入 $\lambda = 2$），会计算出 $(3, 4)$ 从而错选 A；若误将比例看作 $|AP|:|PB| = 1:2$ 的外分点（代入 $\lambda = -\frac{1}{2}$），会计算出 $(-2, -1)$ 从而错选 B。 \\
    故选 C。
\end{solution}


