\begin{question}
    求右图中三角形 $ABC$ 的面积： \paren[C]

    \vspace{0cm}
    \begin{minipage}{0.4\textwidth}
        \begin{choices}
            \item 8.5 
            \item 9.0 
            \item 9.5 
            \item 10.0
        \end{choices}
    \end{minipage}%
    \begin{minipage}{0.6\textwidth}
        \centering
        \begin{tikzpicture}[scale=0.6]
            % 画浅色网格辅助线
            % \draw[help lines, color=gray!30, dashed] (0,0) grid (6,7);

            % 画 x 轴和 y 轴
            \draw[->, thick] (-0.5,0) -- (8,0) node[right] {$x$};
            \draw[->, thick] (0,-0.5) -- (0,8) node[above] {$y$};

            % 原点
            \node[below left] at (0,0) {$O$};

            % 定义三角形顶点坐标
            \coordinate (A) at (1,1);
            \coordinate (B) at (5,2);
            \coordinate (C) at (2,6);

            % 绘制三角形并填充浅蓝色
            \draw[thick, blue, fill=blue!10] (A) -- (B) -- (C) -- cycle;

            % 画出顶点并标出坐标
            \filldraw[black] (A) circle (2pt) node[below right] {$A(1,1)$};
            \filldraw[black] (B) circle (2pt) node[below right] {$B(5,2)$};
            \filldraw[black] (C) circle (2pt) node[above] {$C(2,6)$};
        \end{tikzpicture}
    \end{minipage}
\end{question}


\begin{solution}
    \textbf{解析：}
    \begin{itemize}
        \item \textbf{解法1（割补法）：} 构造包围三角形的矩形（长 $4$ 宽 $5$），减去三个直角三角形。\\
        $S_{\text{矩形}} = 4 \times 5 = 20$ \\
        $S_1 = \frac{1}{2} \times 4 \times 1 = 2$ \\
        $S_2 = \frac{1}{2} \times 3 \times 4 = 6$ \\
        $S_3 = \frac{1}{2} \times 1 \times 5 = 2.5$ \\
        $S_{ABC} = 20 - 2 - 6 - 2.5 = 9.5 \quad (\checkmark)$

        \item \textbf{解法2（鞋带公式）：} \\
        $S_{ABC} = \frac{1}{2} |(x_A y_B + x_B y_C + x_C y_A) - (y_A x_B + y_B x_C + y_C x_A)|$ \\
        $S_{ABC} = \frac{1}{2} |(1 \times 2 + 5 \times 6 + 2 \times 1) - (1 \times 5 + 2 \times 2 + 6 \times 1)|$ \\
        $S_{ABC} = \frac{1}{2} |(2 + 30 + 2) - (5 + 4 + 6)|$ \\
        $S_{ABC} = \frac{1}{2} |34 - 15| = 9.5 \quad (\checkmark)$
    \end{itemize}
    故选 C。
\end{solution}

\begin{question}
    已知平面直角坐标系中点 $A(1, 4)$，点 $B$ 落在 $x$ 轴上。若点 $A$ 与点 $B$ 之间的距离为 $5$，则点 $B$ 的坐标为： \paren[D]
    \begin{choices}
        \item $(4, 0)$ \item $(-2, 0)$ \item $(3, 0)$ 或 $(-3, 0)$ \item $(4, 0)$ 或 $(-2, 0)$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    1. 因为点 $B$ 在 $x$ 轴上，可设点 $B$ 的坐标为 $(x, 0)$。 \\
    2. 根据两点间距离公式 $|AB| = \sqrt{(x - 1)^2 + (0 - 4)^2} = 5$。 \\
    3. 两边平方得：$(x - 1)^2 + (-4)^2 = 25$。 \\
    4. 整理得：$(x - 1)^2 + 16 = 25 \Rightarrow (x - 1)^2 = 9$。 \\
    5. 开方得：$x - 1 = 3$ 或 $x - 1 = -3$。 \\
    6. 解得：$x = 4$ 或 $x = -2$。 \\
    所以点 $B$ 的坐标为 $(4, 0)$ 或 $(-2, 0)$。 \\
    故选 D。
\end{solution}

\begin{question}
    计算 $\displaystyle \sqrt{12} + \sqrt{\frac{1}{3}} - \frac{6}{\sqrt{3}} + \sqrt{27}$ 的结果是： \paren[C]
    \begin{choices}
        \item $\displaystyle 2\sqrt{3}$ 
        \item $\displaystyle 3\sqrt{3}$ 
        \item $\displaystyle \frac{10\sqrt{3}}{3}$ 
        \item $\displaystyle \frac{13\sqrt{3}}{3}$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    {\Large
    \begin{itemize}
        \item $\displaystyle \sqrt{12} = 2\sqrt{3}$
        \item $\displaystyle \sqrt{\frac{1}{3}} = \frac{\sqrt{3}}{3}$
        \item $\displaystyle \frac{6}{\sqrt{3}} = \frac{6\sqrt{3}}{3} = 2\sqrt{3}$
        \item $\displaystyle \sqrt{27} = 3\sqrt{3}$
    \end{itemize}
    }
    \textbf{合并同类根式：} \\
    $\displaystyle 2\sqrt{3} + \frac{\sqrt{3}}{3} - 2\sqrt{3} + 3\sqrt{3}$ \\
    $\displaystyle = (2 - 2 + 3)\sqrt{3} + \frac{\sqrt{3}}{3}$ \\
    $\displaystyle = 3\sqrt{3} + \frac{\sqrt{3}}{3}$ \\
    $\displaystyle = \frac{10\sqrt{3}}{3}$ \\
    故选 C。
\end{solution}

\begin{question}
    化简二次不尽根式 $\displaystyle \sqrt{7 - 4\sqrt{3}}$ 的结果是： \paren[B]
    \begin{choices}
        \item $\displaystyle \sqrt{3} - 2$ 
        \item $\displaystyle 2 - \sqrt{3}$ 
        \item $\displaystyle \sqrt{3} - \sqrt{2}$ 
        \item $\displaystyle 2 + \sqrt{3}$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    我们要将 $\displaystyle \sqrt{7 - 4\sqrt{3}}$ 化简，目标是将其被开方数凑成一个完全平方式。 \\

    1. **观察与变形**：将 $4\sqrt{3}$ 写成 $2\sqrt{ab}$ 的形式：
    $\displaystyle 4\sqrt{3} = 2 \times 2\sqrt{3} = 2\sqrt{4 \times 3} = 2\sqrt{12}$。 \\

    2. **寻找数值**：我们需要找到两个数 $x$ 和 $y$，使得：
    $\begin{cases} x + y = 7 \\ xy = 12 \end{cases}$ \\
    通过观察或解方程可知，$x=4$，$y=3$ 满足条件。 \\

    3. **构造完全平方**：
    $\displaystyle 7 - 4\sqrt{3} = 4 + 3 - 2\sqrt{4 \times 3} = (\sqrt{4})^2 + (\sqrt{3})^2 - 2\sqrt{4}\sqrt{3} = (2 - \sqrt{3})^2$。 \\

    4. **开方得出结果**：
    $\displaystyle \sqrt{7 - 4\sqrt{3}} = \sqrt{(2 - \sqrt{3})^2} = |2 - \sqrt{3}|$。 \\
    由于 $2 = \sqrt{4} > \sqrt{3}$，所以 $2 - \sqrt{3}$ 为正数。 \\
    结果为 $\displaystyle 2 - \sqrt{3}$。 \\

    \textbf{易错点}：选项 A 的数值虽然正确，但根式化简结果必须为非负数，$\sqrt{3}-2$ 是负数，故排除。 \\
    故选 B。
\end{solution}

\begin{question}
    已知 $x > 0$ 且 $x \neq 1$，化简表达式 $\displaystyle \frac{x-1}{\sqrt{x}+1} \cdot \sqrt{x}$ 的结果是： \paren[B]
    \begin{choices}
        \item $\displaystyle x + \sqrt{x}$ 
        \item $\displaystyle x - \sqrt{x}$ 
        \item $\displaystyle \sqrt{x} - 1$ 
        \item $\displaystyle x - 1$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    这道题有两种常用的处理方法：

    \textbf{方法一：分母有理化} \\
    将第一项的分式分子、分母同时乘以 $(\sqrt{x}-1)$：
    $$\frac{(x-1)(\sqrt{x}-1)}{(\sqrt{x}+1)(\sqrt{x}-1)} \cdot \sqrt{x}$$
    根据平方差公式 $(a+b)(a-b)=a^2-b^2$，分母变为 $(\sqrt{x})^2 - 1^2 = x-1$：
    $$\frac{(x-1)(\sqrt{x}-1)}{x-1} \cdot \sqrt{x}$$
    约去 $(x-1)$，得：
    $$(\sqrt{x}-1) \cdot \sqrt{x} = (\sqrt{x})^2 - \sqrt{x} = x - \sqrt{x}$$

    \textbf{方法二：分子因式分解（更简便）} \\
    观察到分子 $x-1$ 可以写成 $(\sqrt{x})^2 - 1^2$，利用平方差公式展开：
    $$\frac{(\sqrt{x}+1)(\sqrt{x}-1)}{\sqrt{x}+1} \cdot \sqrt{x}$$
    直接约去 $(\sqrt{x}+1)$，得：
    $$(\sqrt{x}-1) \cdot \sqrt{x} = x - \sqrt{x}$$

    故选 B。
\end{solution}

\begin{question}
    已知直线 $l$ 经过点 $P(1, 2)$，且与以 $A(-1, 0)$ 和 $B(0, 2)$ 为端点的线段 $AB$ 相交，则直线 $l$ 的斜率 $k$ 的取值范围是： \paren[A]
    \begin{choices}
        \item $k \geq 1$ 或 $k \leq 0$ 
        \item $0 \leq k \leq 1$ 
        \item $k \geq 1$ 
        \item $k \leq 1$
    \end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    我们要考虑直线 $l$ 绕着定点 $P(1, 2)$ 旋转，并保持与线段 $AB$ 有交点。我们可以通过计算点 $P$ 与线段两个端点的连线斜率来确定临界值。

    1. **计算临界斜率**：
    \begin{itemize}
        \item 直线 $PA$ 的斜率：$k_{PA} = \frac{2 - 0}{1 - (-1)} = \frac{2}{2} = 1$。
        \item 直线 $PB$ 的斜率：$k_{PB} = \frac{2 - 2}{1 - 0} = \frac{0}{1} = 0$。
    \end{itemize}

    2. **结合图形分析**（想象或画出坐标系）：
    \begin{itemize}
        \item 当直线 $l$ 从 $PB$（斜率为 $0$）顺时针旋转时，斜率 $k$ 变小（变为负数），直到直线变为垂直状态（斜率不存在）。
        \item 当直线 $l$ 从 $PA$（斜率为 $1$）逆时针旋转时，斜率 $k$ 变大，直到直线变为垂直状态。
    \end{itemize}

    3. **结论**：
    由于直线在 $PB$ 之下或 $PA$ 之上都能与线段 $AB$ 相交（注意：当直线趋于垂直时，斜率趋向正无穷或负无穷），因此：
    $k \geq k_{PA}$ 或 $k \leq k_{PB}$，即 $k \geq 1$ 或 $k \leq 0$。

    \textbf{陷阱提示}：很多学生会误以为范围是在两个斜率中间（$0 \leq k \leq 1$），那是点 $P$ 在线段 $AB$ 左侧时的情况。本题中点 $P$ 在右侧，旋转轨迹跨越了斜率不存在的垂直位置。

    故选 A。
\end{solution}

\newpage
\begin{question}
    已知直线的方程为 $ax + by + c = 0$，若满足 $ab > 0$ 且 $bc < 0$，则该直线的图像可能是： \paren[B]

    \vspace{0.5cm}
    \begin{choices}
    \item
    \begin{minipage}{0.22\textwidth}
        \centering
        \begin{tikzpicture}[scale=0.4]
            \draw[->] (-2,0) -- (2,0) node[right] {\tiny $x$};
            \draw[->] (0,-2) -- (0,2) node[above] {\tiny $y$};
            \draw[thick, blue] (-1.5,-1.5) -- (1.5,1.5);
        \end{tikzpicture}
    \end{minipage}
    \item 
    \begin{minipage}{0.22\textwidth}
        \centering
        \begin{tikzpicture}[scale=0.4]
            \draw[->] (-2,0) -- (2,0) node[right] {\tiny $x$};
            \draw[->] (0,-2) -- (0,2) node[above] {\tiny $y$};
            \draw[thick, blue] (-1.5,1.5) -- (1.5,-0.5);
        \end{tikzpicture}
    \end{minipage}
    \item
    \begin{minipage}{0.22\textwidth}
        \centering
        \begin{tikzpicture}[scale=0.4]
            \draw[->] (-2,0) -- (2,0) node[right] {\tiny $x$};
            \draw[->] (0,-2) -- (0,2) node[above] {\tiny $y$};
            \draw[thick, blue] (-1.5,0.5) -- (1.5,-1.5);
        \end{tikzpicture}
    \end{minipage}
    \item
    \begin{minipage}{0.22\textwidth}
        \centering
        \begin{tikzpicture}[scale=0.4]
            \draw[->] (-2,0) -- (2,0) node[right] {\tiny $x$};
            \draw[->] (0,-2) -- (0,2) node[above] {\tiny $y$};
            \draw[thick, blue] (-1.5,-0.5) -- (1.5,1.5);
        \end{tikzpicture}
    \end{minipage}
\end{choices}
\end{question}

\begin{solution}
    \textbf{解析：} \\
    1. 将一般式方程 $ax + by + c = 0$ 转化为斜截式：$y = -\frac{a}{b}x - \frac{c}{b}$。
    \begin{itemize}
        \item 斜率 $k = -\frac{a}{b}$
        \item $y$ 轴截距 $n = -\frac{c}{b}$
    \end{itemize}

    2. **判断符号**：
    \begin{itemize}
        \item 因为 $ab > 0$，说明 $a, b$ 同号，则 $\frac{a}{b} > 0$，故斜率 $k = -\frac{a}{b} < 0$。直线应向右下方倾斜（排除 A, D）。
        \item 因为 $bc < 0$，说明 $b, c$ 异号，则 $\frac{c}{b} < 0$，故截距 $n = -\frac{c}{b} > 0$。直线与 $y$ 轴的交点应在原点上方。
    \end{itemize}

    3. **结论**：
    斜率为负且 $y$ 轴截距为正的图像只有 B。

    故选 B。
\end{solution}

